llm.raw_content:
{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "A glucose-bearing analogue (2b) reached 3.1 nmol/g in rat brain after systemic dosing, with transport attributed to GLUT1; the query's β-D-glucose moiety makes this transporter-mediated CNS access directly relevant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Hydroxysafflor yellow A, a large polar glycosylated natural product, reached 1026 ng/g in rat brain in a tissue distribution study, demonstrating that high polarity does not preclude meaningful BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The complex glycosylated triterpenoid A-VI penetrated the BBB in rats, with a brain concentration of 248.7 ng/g, supporting CNS access for bulky glycoside scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "BA10, a glycosylated triterpenoid, showed high brain uptake and reversible tracer kinetics in pigs, providing in vivo evidence that large glycosides can access the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The glucoside DP had a brain/plasma ratio of 0.80 in mice, indicating ready brain entry for a glucose-containing compound.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the query is very polar and unlikely to cross the BBB by passive diffusion, multiple glycosylated natural products with similar glucose-containing scaffolds show measurable brain penetration, often via glucose transporter-mediated uptake; therefore meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or uptake measurement exists for the query molecule itself.",
    "The query's bulky diterpenoid aglycone and benzoyl ester may reduce GLUT1 recognition compared with smaller glucose conjugates.",
    "Efflux liability is inferred from physicochemical properties but not experimentally confirmed for this exact scaffold.",
    "Most supportive glycoside data come from rodents or disease models; human CNS exposure is not established."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

